import type { BankQuestion } from "@/lib/bank";

/** Definite Integrals and Area (Mathematics (JEE)): 177 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"math-definite-integrals-area-1","question":"∫₀² (3x² + 1) dx equals:","options":["8","10","12","14"],"answer":1,"explanation":"The antiderivative is x³ + x, so the value is (8 + 2) − 0 = 10. Forgetting to integrate the constant 1 gives 8, the most common slip.","difficulty":"easy","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-2","question":"∫₀^(π/4) sec²x dx equals:","options":["0","√2","1","π/4"],"answer":2,"explanation":"Since d/dx(tan x) = sec²x, the integral is tan(π/4) − tan 0 = 1. Answering π/4 comes from integrating as if sec²x were 1, and √2 from evaluating sec instead of tan.","difficulty":"easy","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-3","question":"The area bounded by y = x², the x-axis and the lines x = 0 and x = 3 is:","options":["9","27","3","6"],"answer":0,"explanation":"Area = ∫₀³ x² dx = [x³/3]₀³ = 27/3 = 9. Writing 27 means forgetting to divide by 3 after raising the power.","difficulty":"easy","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-4", "question": "With [x] the greatest integer function, ∫₀³ [x] dx equals:", "options": ["6", "4.5", "2", "3"], "answer": 3, "explanation": "[x] = 0, 1, 2 on [0, 1), [1, 2), [2, 3), so the integral is 0 + 1 + 2 = 3. 4.5 is ∫₀³ x dx.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-5", "question": "∫₀^π |cos x| dx equals:", "options": ["0", "1", "2", "π"], "answer": 2, "explanation": "|cos x| = cos x on [0, π/2] and −cos x on [π/2, π]; each piece gives 1, total 2. Without the modulus the integral would be 0.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-6","question":"∫₀¹ x eˣ dx equals:","options":["1","e − 1","e","2 − e"],"answer":0,"explanation":"By parts, ∫ x eˣ dx = (x − 1)eˣ, so the value is 0·e − (−1)·1 = 1. The tempting e − 1 comes from evaluating only the eˣ part and forgetting the x eˣ term.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-7", "question": "∫₂⁸ √x/(√x + √(10 − x)) dx equals:", "options": ["6", "5", "4", "3"], "answer": 3, "explanation": "Replacing x by 2 + 8 − x = 10 − x swaps √x and √(10 − x). Adding the two forms gives 2I = ∫₂⁸ 1 dx = 6, so I = 3.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-8","question":"The area bounded by y = √x, the x-axis and the line x = 4 is:","options":["8","16/3","8/3","32/3"],"answer":1,"explanation":"∫₀⁴ √x dx = (2/3)x^(3/2) from 0 to 4 = (2/3)(8) = 16/3. Forgetting the 2/3 gives 8, and doubling or halving it by a power slip gives 32/3 or 8/3.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-9", "question": "If F(x) = ∫ₓ^(3x) (1/t) dt for x > 0, then F′(x) equals:", "options": ["2/x", "0", "1/(3x)", "ln 3"], "answer": 1, "explanation": "By Leibniz's rule F′(x) = (1/(3x))·3 − (1/x)·1 = 0. Indeed F(x) = ln 3x − ln x = ln 3, a constant.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-10", "question": "∫₀^(10π) |sin x + cos x| dx equals:", "options": ["20", "10√2", "40", "20√2"], "answer": 3, "explanation": "sin x + cos x = √2 sin(x + π/4). |sin| has period π with ∫ over one period = 2, and 10π holds 10 periods, so the integral is √2 × 10 × 2 = 20√2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-11", "question": "With [·] the greatest integer function, ∫₀² [x²] dx equals:", "options": ["5 − √2 − √3", "3 − √2", "5 + √2 + √3", "6 − √3"], "answer": 0, "explanation": "[x²] = 0 on [0, 1), 1 on [1, √2), 2 on [√2, √3), 3 on [√3, 2). Integral = (√2 − 1) + 2(√3 − √2) + 3(2 − √3) = 5 − √2 − √3.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "math-definite-integrals-area-12", "question": "∫₋₁² |x² − x| dx equals:", "options": ["3/2", "5/6", "11/6", "7/6"], "answer": 2, "explanation": "x² − x ≥ 0 on [−1, 0] and [1, 2], and ≤ 0 on [0, 1]. Pieces: [x³/3 − x²/2] from −1 to 0 = 5/6; ∫₀¹ (x − x²) = 1/6; [x³/3 − x²/2] from 1 to 2 = 2/3 + 1/6 = 5/6. Total 11/6.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-13", "question": "The area enclosed between the parabolas y = x² and y = 2 − x² is:", "options": ["4/3", "2", "16/3", "8/3"], "answer": 3, "explanation": "They meet where x² = 2 − x², i.e. x = ±1. Area = ∫₋₁¹ (2 − 2x²) dx = [2x − 2x³/3] from −1 to 1 = 2(2 − 2/3) = 8/3.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-14", "question": "∫₀^π x sin²x dx equals:", "options": ["π²/2", "π²/4", "π/2", "π²/8"], "answer": 1, "explanation": "Using x → π − x: I = ∫₀^π (π − x) sin²x dx, so 2I = π∫₀^π sin²x dx = π × π/2 and I = π²/4.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-15", "question": "∫₀¹ tan⁻¹x dx equals:", "options": ["π/4 + (1/2) ln 2", "π/4 − ln 2", "π/4 − (1/2) ln 2", "π/2 − ln 2"], "answer": 2, "explanation": "By parts: [x tan⁻¹x]₀¹ − ∫₀¹ x/(1 + x²) dx = π/4 − (1/2) ln 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-16", "question": "The area of the region bounded by y = |x| and y = 2 − x² is:", "options": ["7/3", "7/6", "10/3", "5/3"], "answer": 0, "explanation": "For x ≥ 0 the curves meet where x = 2 − x², i.e. x = 1. By symmetry the area is 2∫₀¹ (2 − x² − x) dx = 2(2 − 1/3 − 1/2) = 2 × 7/6 = 7/3.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-17", "question": "lim (x → 0) (∫₀ˣ t sin t dt)/x³ equals:", "options": ["1", "1/3", "0", "1/2"], "answer": 1, "explanation": "It is a 0/0 form; by L'Hôpital and Leibniz the limit is lim x sin x/(3x²) = lim (sin x/x)/3 = 1/3.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-18", "question": "∫₀^(π/2) sin⁶x dx equals:", "options": ["5π/16", "3π/16", "5π/32", "8/15"], "answer": 2, "explanation": "Wallis: (5·3·1)/(6·4·2) × π/2 = (15/48)(π/2) = 5π/32. 8/15 is the odd-power formula, which applies to sin⁵x.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-19", "question": "The integral of cos x/(1 + eˣ) from x = −π/2 to x = π/2 equals:", "options": ["1", "2", "0", "1/2"], "answer": 0, "explanation": "Replacing x by −x gives I = ∫ eˣ cos x/(1 + eˣ) dx over the same limits. Adding the two forms: 2I = integral of cos x from −π/2 to π/2 = 2, so I = 1.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "math-definite-integrals-area-20", "question": "Consider the following statements:\n(1) ∫₀^(2a) f(x) dx = 2∫₀ᵃ f(x) dx whenever f(2a − x) = f(x).\n(2) If f has period T, then ∫₀^(nT) f(x) dx = n∫₀^T f(x) dx for every positive integer n.\n(3) ∫₋₁¹ [x] dx = 0, where [x] is the greatest integer function.\n(4) If f is continuous and non-negative on [a, b] (a < b) and ∫ₐᵇ f(x) dx = 0, then f(x) = 0 throughout [a, b].\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) and (2) are standard properties, both true. (3) False: [x] = −1 on [−1, 0) and 0 on [0, 1), so the integral is −1; [x] is not odd. (4) True: a continuous f positive at one point is positive on a small interval, which would make the integral positive. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-21", "question": "The area of the region common to y² ≤ 2x and x² ≤ 2y is:", "options": ["16/3", "8/3", "4/3", "2/3"], "answer": 2, "explanation": "The parabolas meet at (0, 0) and (2, 2). Area = ∫₀² (√(2x) − x²/2) dx = √2·(2/3)·2^(3/2) − 8/6 = 8/3 − 4/3 = 4/3 (this is 16a²/3 with 4a = 2).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-22", "question": "The area of the region {(x, y): 0 ≤ y ≤ x² + 1, 0 ≤ y ≤ x + 1, 0 ≤ x ≤ 2} is:", "options": ["23/6", "14/3", "4", "19/6"], "answer": 0, "explanation": "x² + 1 ≤ x + 1 exactly when 0 ≤ x ≤ 1. Area = ∫₀¹ (x² + 1) dx + ∫₁² (x + 1) dx = 4/3 + [x²/2 + x]₁² = 4/3 + (4 − 3/2) = 4/3 + 5/2 = 23/6.", "difficulty": "very-hard", "source": "JEE Main 2021 pattern"},
  {"id": "math-definite-integrals-area-23", "question": "∫₀^(π/2) ln(sin x) dx equals:", "options": ["(π/2) ln 2", "−π ln 2", "−(π/4) ln 2", "−(π/2) ln 2"], "answer": 3, "explanation": "I equals ∫₀^(π/2) ln cos x dx, so 2I = ∫₀^(π/2) ln(sin 2x/2) dx = ∫₀^(π/2) ln sin 2x dx − (π/2) ln 2. With t = 2x the first integral is (1/2)∫₀^π ln sin t dt = I. So 2I = I − (π/2) ln 2 and I = −(π/2) ln 2.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-definite-integrals-area-24", "question": "The area of the smaller region cut off from the disc x² + y² ≤ 4 by the line x + y = 2 is:", "options": ["2π − 2", "π − 2", "π + 2", "π/2 − 1"], "answer": 1, "explanation": "The chord joins (2, 0) and (0, 2). The first-quadrant sector has area (1/4)π(4) = π, and the triangle with vertices O, (2, 0), (0, 2) has area 2, so the segment's area is π − 2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-25", "question": "With [·] the greatest integer function, ∫₀² [x² − x + 1] dx equals:", "options": ["(3 − √5)/2", "(5 − √5)/2", "2", "(5 + √5)/2"], "answer": 1, "explanation": "x² − x + 1 < 1 on (0, 1), so the integrand is 0 there. It equals 1 on [1, (1 + √5)/2), where x² − x + 1 < 2, and 2 on [(1 + √5)/2, 2), where it stays below 3. Integral = ((1 + √5)/2 − 1) + 2(2 − (1 + √5)/2) = (√5 − 1)/2 + 3 − √5 = (5 − √5)/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-26", "question": "The local maximum value of f(x) = ∫₀ˣ (t² − 3t + 2) dt is:", "options": ["2/3", "1", "0", "5/6"], "answer": 3, "explanation": "f′(x) = x² − 3x + 2 = (x − 1)(x − 2) changes from + to − at x = 1, so the local maximum is at x = 1. f(x) = x³/3 − 3x²/2 + 2x, so f(1) = 1/3 − 3/2 + 2 = 5/6. 2/3 = f(2) is the local minimum.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-27", "question": "lim (n → ∞) Σ (r = 1 to n) r²/(n³ + r³) equals:", "options": ["(1/3) ln 2", "ln 2", "(1/2) ln 2", "1/3"], "answer": 0, "explanation": "Write the term as (1/n)·(r/n)²/(1 + (r/n)³). The sum tends to ∫₀¹ x²/(1 + x³) dx = (1/3) ln(1 + x³) from 0 to 1 = (1/3) ln 2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-28", "question": "Assertion (A): ∫₀^π cos⁵x dx = 0.\nReason (R): If f(2a − x) = −f(x), then ∫₀^(2a) f(x) dx = 0; and cos⁵(π − x) = −cos⁵x.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "With 2a = π, f(π − x) = (−cos x)⁵ = −f(x), so the halves [0, π/2] and [π/2, π] cancel. R is true and is exactly the reason A holds.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-29", "question": "With {x} = x − [x] the fractional part, ∫₀^3.5 {x} dx equals:", "options": ["7/4", "3/2", "15/8", "13/8"], "answer": 3, "explanation": "{x} has period 1 and ∫₀¹ x dx = 1/2, so [0, 3] contributes 3 × 1/2 = 3/2. On [3, 3.5], {x} = x − 3 and contributes ∫₀^0.5 t dt = 1/8. Total 13/8.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-30", "question": "The total area enclosed between y = sin x and y = sin 2x for 0 ≤ x ≤ π is:", "options": ["2", "5/2", "9/4", "3/2"], "answer": 1, "explanation": "sin 2x = sin x gives sin x(2cos x − 1) = 0, so x = 0, π/3, π. On [0, π/3], sin 2x ≥ sin x: [−cos 2x/2 + cos x] from 0 to π/3 = 3/4 − 1/2 = 1/4. On [π/3, π], sin x ≥ sin 2x: [−cos x + cos 2x/2] from π/3 to π = 3/2 − (−3/4) = 9/4. Total 1/4 + 9/4 = 5/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-31", "question": "∫₋₂² (x³ + x⁵ cos x + 3) dx equals:", "options": ["16", "0", "6", "12"], "answer": 3, "explanation": "x³ and x⁵ cos x are odd functions, so their integrals over [−2, 2] vanish. What remains is ∫₋₂² 3 dx = 3 × 4 = 12.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-32", "question": "∫₁^e (ln x)/x dx equals:", "options": ["1/2", "1", "e − 1", "2"], "answer": 0, "explanation": "Put t = ln x, dt = dx/x; the limits become 0 to 1, so the integral is ∫₀¹ t dt = 1/2.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-33", "question": "The area of the region enclosed between y = x and y = x² is:", "options": ["1/6", "1/3", "1/2", "1/12"], "answer": 0, "explanation": "They meet at x = 0 and x = 1, with x ≥ x² in between. Area = ∫₀¹ (x − x²) dx = 1/2 − 1/3 = 1/6.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-34", "question": "∫₀¹ x(1 − x)⁹ dx equals:", "options": ["1/11", "1/90", "1/10", "1/110"], "answer": 3, "explanation": "Replace x by 1 − x: ∫₀¹ (1 − x)x⁹ dx = ∫₀¹ (x⁹ − x¹⁰) dx = 1/10 − 1/11 = 1/110.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-35", "question": "∫₀^(π/4) tan²x dx equals:", "options": ["π/4 − 1/2", "π/4", "1 + π/4", "1 − π/4"], "answer": 3, "explanation": "tan²x = sec²x − 1, so the integral is [tan x − x] from 0 to π/4 = 1 − π/4.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-36", "question": "With [x] the greatest integer function, ∫₀² x[x] dx equals:", "options": ["3/2", "2", "1", "5/2"], "answer": 0, "explanation": "On [0, 1) the integrand is 0; on [1, 2) it is x. So the integral is ∫₁² x dx = (4 − 1)/2 = 3/2.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-37", "question": "The area of the region bounded by the parabola y = x² and the line y = 4 is:", "options": ["8", "16/3", "32/3", "64/3"], "answer": 2, "explanation": "They meet at x = ±2. Area = ∫₋₂² (4 − x²) dx = 16 − 16/3 = 32/3. 16/3 counts only the half with x ≥ 0.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-38", "question": "∫₀^π sin³x dx equals:", "options": ["3π/8", "2/3", "0", "4/3"], "answer": 3, "explanation": "sin³x = (3 sin x − sin 3x)/4. ∫₀^π sin x dx = 2 and ∫₀^π sin 3x dx = 2/3, so the integral is (6 − 2/3)/4 = 4/3. It is not 0, since sin³x ≥ 0 on [0, π].", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-39", "question": "The area enclosed by the ellipse x²/9 + y²/4 = 1 is:", "options": ["6π", "9π", "4π", "36π"], "answer": 0, "explanation": "Area = 4∫₀³ (2/3)√(9 − x²) dx = (8/3) × (9π/4) = 6π, i.e. πab with a = 3, b = 2.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-40", "question": "A continuous function f satisfies ∫₀ˣ f(t) dt = x² + ∫ₓ¹ t² f(t) dt + C for all x, where C is a constant. Then f(1/2) equals:", "options": ["8/5", "1/2", "2/5", "4/5"], "answer": 3, "explanation": "Differentiating (C drops out): f(x) = 2x − x² f(x), so f(x) = 2x/(1 + x²) and f(1/2) = 1/(1 + 1/4) = 4/5.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-41", "question": "∫₀¹ √((1 − x)/(1 + x)) dx equals:", "options": ["π/4", "π/2 + 1", "π/2 − 1", "1 − π/4"], "answer": 2, "explanation": "√((1 − x)/(1 + x)) = (1 − x)/√(1 − x²). So the integral is ∫₀¹ dx/√(1 − x²) − ∫₀¹ x dx/√(1 − x²) = π/2 − [−√(1 − x²)]₀¹ = π/2 − 1.", "difficulty": "hard", "source": "JEE Main · CBSE pattern"},
  {"id": "math-definite-integrals-area-42", "question": "∫₀^∞ dx/(x² + 4x + 8) equals:", "options": ["π/4", "π/8", "π/2", "3π/8"], "answer": 1, "explanation": "x² + 4x + 8 = (x + 2)² + 4, so the antiderivative is (1/2) tan⁻¹((x + 2)/2). Value = (1/2)(π/2 − π/4) = π/8.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-43", "question": "The area bounded by the curve x² = 4y and the line x = 4y − 2 is:", "options": ["7/8", "9/4", "9/8", "3/4"], "answer": 2, "explanation": "Substituting 4y = x² into x = 4y − 2 gives x² − x − 2 = 0, x = −1 or 2. Area = ∫₋₁² [(x + 2)/4 − x²/4] dx = (1/4)[x²/2 + 2x − x³/3] from −1 to 2 = (1/4)(10/3 + 7/6) = 9/8.", "difficulty": "hard", "source": "JEE Main · CBSE pattern"},
  {"id": "math-definite-integrals-area-44", "question": "∫₀^(π/2) sin 2x · ln(tan x) dx equals:", "options": ["π/4", "ln 2", "0", "−ln 2"], "answer": 2, "explanation": "Replacing x by π/2 − x keeps sin 2x and turns ln(tan x) into ln(cot x) = −ln(tan x). So I = −I and I = 0.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-45", "question": "The area of the region enclosed between y = |x − 1| and y = 3 − |x| is:", "options": ["6", "3", "4", "2"], "answer": 2, "explanation": "They meet at (−1, 2) and (2, 1); the region has vertices (−1, 2), (0, 3), (2, 1), (1, 0). By the shoelace formula the area is |−3 − 6 − 1 + 2|/2 = 4. (It is a rectangle with sides √2 and 2√2.)", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-46", "question": "∫₀^(π/2) sin x cos x/(sin⁴x + cos⁴x) dx equals:", "options": ["π/4", "π/2", "π/8", "1/2"], "answer": 0, "explanation": "Put t = sin²x, dt = 2 sin x cos x dx: the integral is (1/2)∫₀¹ dt/(t² + (1 − t)²) = (1/2)∫₀¹ dt/(2(t − 1/2)² + 1/2) = (1/2)[tan⁻¹(2t − 1)]₀¹ = (1/2)(π/4 + π/4) = π/4.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-47", "question": "∫₁² eˣ(1/x − 1/x²) dx equals:", "options": ["e² − e", "e²/2 − e", "e²/4 − e", "e(e − 2)"], "answer": 1, "explanation": "∫eˣ(g + g′) dx = eˣ g with g = 1/x, g′ = −1/x². So the value is [eˣ/x]₁² = e²/2 − e.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-48", "question": "The area enclosed between y = sin x and y = cos x for 0 ≤ x ≤ π/2 (both parts) is:", "options": ["2√2 − 2", "√2 − 1", "2 − √2", "2√2"], "answer": 0, "explanation": "They cross at π/4. ∫₀^(π/4) (cos x − sin x) dx = √2 − 1 and ∫ from π/4 to π/2 of (sin x − cos x) dx = √2 − 1. Total = 2√2 − 2. Integrating sin x − cos x straight across gives 0.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-49","question":"Consider the following statements:\n(1) ∫₋₁¹ |x| dx = 2.\n(2) d/dx ∫₀^(x²) sin t dt = 2x sin(x²).\n(3) If f is odd, then ∫₋ₐᵃ f(x) dx = 2∫₀ᵃ f(x) dx.\n(4) ∫₀^(2π) |sin x| dx = 2.\nHow many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"(1) False: two triangles of area 1/2 give 1. (2) True: Leibniz rule gives sin(x²) × 2x. (3) False: for odd f the integral is 0; the doubling rule is for even f. (4) False: the area is 2 on each of [0, π] and [π, 2π], so 4. Only one is correct.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-50", "question": "The area of the region {(x, y): x ≥ 0, xy ≤ 8, 1 ≤ y ≤ x²} is:", "options": ["16 ln 2 − 14/3", "16 ln 2 − 6", "8 ln 2 − 14/3", "16 ln 2 + 4/3"], "answer": 0, "explanation": "x² = 8/x at x = 2. For 1 ≤ x ≤ 2, y runs from 1 to x²: ∫₁² (x² − 1) dx = 4/3. For 2 ≤ x ≤ 8, y runs from 1 to 8/x: ∫₂⁸ (8/x − 1) dx = 16 ln 2 − 6. Total = 16 ln 2 − 14/3.", "difficulty": "very-hard", "source": "JEE Main 2019 pattern"},
  {"id": "math-definite-integrals-area-51", "question": "If Iₙ = ∫₀^(π/4) tanⁿx dx, then 1/(I₂ + I₄), 1/(I₃ + I₅), 1/(I₄ + I₆) are in:", "options": ["HP", "GP", "AP", "none of these progressions"], "answer": 2, "explanation": "Iₙ + Iₙ₊₂ = ∫₀^(π/4) tanⁿx sec²x dx = 1/(n + 1). So the three numbers are 3, 4, 5, which form an AP.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-52", "question": "∫₀¹ ln(1 + x)/(1 + x²) dx equals:", "options": ["(π/4) ln 2", "(π/8) ln 2", "(π/2) ln 2", "π/8"], "answer": 1, "explanation": "Put x = tan θ: I = ∫₀^(π/4) ln(1 + tan θ) dθ. Replacing θ by π/4 − θ gives 1 + tan(π/4 − θ) = 2/(1 + tan θ), so I = ∫₀^(π/4) ln 2 dθ − I, 2I = (π/4) ln 2, I = (π/8) ln 2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-53", "question": "The area bounded by the parabola y = x² − 4x + 3 and its tangents at (0, 3) and (3, 0) is:", "options": ["9/2", "9/4", "3/2", "9/8"], "answer": 1, "explanation": "y′ = 2x − 4: tangents y = −4x + 3 and y = 2x − 6, meeting at (3/2, −3). Parabola minus tangent is x² on [0, 3/2] and (x − 3)² on [3/2, 3]. Area = (3/2)³/3 × 2 = 9/4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-54", "question": "lim (n → ∞) (1/n)[(n + 1)(n + 2)⋯(2n)]^(1/n) equals:", "options": ["e/4", "2/e", "4/e", "4"], "answer": 2, "explanation": "Take logs: (1/n) Σ (r = 1 to n) ln(1 + r/n) → ∫₀¹ ln(1 + x) dx = [(1 + x)ln(1 + x) − x]₀¹ = 2 ln 2 − 1. The limit is e^(2 ln 2 − 1) = 4/e.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-55", "question": "∫₋π^π 2x(1 + sin x)/(1 + cos²x) dx equals:", "options": ["π²/2", "π²", "0", "2π²"], "answer": 1, "explanation": "2x/(1 + cos²x) is odd and integrates to 0. 2x sin x/(1 + cos²x) is even, giving 4∫₀^π x sin x/(1 + cos²x) dx. With x → π − x, that integral is (π/2)∫₀^π sin x/(1 + cos²x) dx = (π/2)(π/2) = π²/4. Total = π².", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-56", "question": "A continuous f satisfies f(x) = x² + x∫₀¹ f(t) dt + ∫₀¹ t f(t) dt. Then f(0) equals:", "options": ["1/2", "17/6", "−5", "−17/6"], "answer": 3, "explanation": "Let A = ∫₀¹ f and B = ∫₀¹ t f, so f(x) = x² + Ax + B. Integrating: A = 1/3 + A/2 + B and B = 1/4 + A/3 + B/2. The second gives B = 1/2 + 2A/3; then A/2 = 5/6 + 2A/3 gives A = −5 and B = −17/6 = f(0).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-57", "question": "Assertion (A): ∫₋₁¹ dx/x² = [−1/x] from −1 to 1 = −2.\nReason (R): If f is continuous on [a, b] and F′ = f there, then ∫ₐᵇ f(x) dx = F(b) − F(a).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is the fundamental theorem of calculus and is true. But 1/x² is not continuous (it is unbounded) at x = 0, so R does not apply; the integral diverges to +∞, and a positive integrand can never give −2. A is false.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-58", "question": "The area of the region bounded by y = sin⁻¹x, y = cos⁻¹x and the x-axis is:", "options": ["2 − √2", "√2 − 1", "π/4", "√2"], "answer": 1, "explanation": "The curves meet at (1/√2, π/4). Using horizontal strips, for 0 ≤ y ≤ π/4 the region runs from x = sin y to x = cos y. Area = ∫₀^(π/4) (cos y − sin y) dy = √2/2 + √2/2 − 1 = √2 − 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-59", "question": "∫₀^(π/2) sin⁵x cos⁴x dx equals:", "options": ["4/315", "8/105", "3π/512", "8/315"], "answer": 3, "explanation": "Wallis: (4 × 2)(3 × 1)/(9 × 7 × 5 × 3 × 1) = 24/945 = 8/315; no factor π/2 since one power is odd. Or put t = cos x: ∫₀¹ (1 − t²)² t⁴ dt = 1/5 − 2/7 + 1/9 = 8/315.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-60", "question": "lim (x → ∞) (∫₀ˣ e^(t²) dt)² / ∫₀ˣ e^(2t²) dt equals:", "options": ["∞", "1", "0", "1/2"], "answer": 2, "explanation": "Both grow without bound, so apply L'Hôpital: 2e^(x²)∫₀ˣ e^(t²) dt / e^(2x²) = 2∫₀ˣ e^(t²) dt / e^(x²). Again: 2e^(x²)/(2x e^(x²)) = 1/x → 0.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-definite-integrals-area-61","question":"∫₋₁¹ ln((2 − x)/(2 + x)) dx equals:","options":["0","ln 3","2 ln 3","−2"],"answer":0,"explanation":"g(x) = ln((2 − x)/(2 + x)) satisfies g(−x) = ln((2 + x)/(2 − x)) = −g(x): it is odd, so its integral over [−1, 1] is 0. No antiderivative is needed.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-62","question":"∫₀¹ x³/(1 + x⁸) dx equals:","options":["π/8","π/16","π/4","π/32"],"answer":1,"explanation":"Put t = x⁴, dt = 4x³ dx: (1/4)∫₀¹ dt/(1 + t²) = (1/4)(π/4) = π/16. Forgetting the 1/4 from dt gives π/4.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-63","question":"The area of the region bounded by y = ln x, the x-axis and the line x = e is:","options":["e − 1","e","1","2"],"answer":2,"explanation":"The curve meets the x-axis at x = 1, so the area is ∫₁ᵉ ln x dx = [x ln x − x]₁ᵉ = (e − e) − (0 − 1) = 1. Using limits 0 to e is wrong since ln x < 0 there and the region is not bounded that way.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-64","question":"If f(x) = ∫ from x² to x³ of dt/ln t (x > 1), then f′(x) equals:","options":["(x³ − x²)/ln x","1/ln x","(3x² − 2x)/ln x","(x² − x)/ln x"],"answer":3,"explanation":"Leibniz rule: f′(x) = 3x²/ln(x³) − 2x/ln(x²) = 3x²/(3 ln x) − 2x/(2 ln x) = (x² − x)/ln x. Forgetting that ln(x³) = 3 ln x gives (3x² − 2x)/ln x.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-65","question":"∫₀^(π/2) dx/(4 cos²x + 9 sin²x) equals:","options":["π/12","π/6","π/24","π/36"],"answer":0,"explanation":"Divide by cos²x and put t = tan x: ∫₀^∞ dt/(4 + 9t²) = (1/9)·(3/2)·[tan⁻¹(3t/2)]₀^∞ = (1/6)(π/2) = π/12. (In general π/(2ab) with a² = 4, b² = 9.)","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-66","question":"∫₀¹ x tan⁻¹x dx equals:","options":["π/4","π/4 − 1/2","1/2 − π/8","π/2 − 1"],"answer":1,"explanation":"By parts: [x²/2 · tan⁻¹x]₀¹ − (1/2)∫₀¹ x²/(1 + x²) dx = π/8 − (1/2)(1 − π/4) = π/8 − 1/2 + π/8 = π/4 − 1/2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-67","question":"The area enclosed between the parabolas y = x² − 2x and y = 4 − x² is:","options":["27/2","8","9","6"],"answer":2,"explanation":"They meet where 2x² − 2x − 4 = 0, i.e. x = −1, 2. Area = ∫₋₁² (4 + 2x − 2x²) dx = [4x + x² − 2x³/3]₋₁² = 20/3 + 7/3 = 9.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-68","question":"∫₀^π x/(1 + sin x) dx equals:","options":["π/2","2π","π²/2","π"],"answer":3,"explanation":"Using x → π − x (sin is unchanged): I = (π/2)∫₀^π dx/(1 + sin x). ∫₀^π dx/(1 + sin x) = ∫₀^π (1 − sin x)/cos²x dx = [tan x − sec x]₀^π = (0 + 1) − (0 − 1) = 2. So I = π.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-69","question":"∫₀^π sin⁵(x/2) dx equals:","options":["16/15","32/15","4/5","8/15"],"answer":0,"explanation":"Put x = 2u: 2∫₀^(π/2) sin⁵u du = 2·(4·2)/(5·3·1) = 2·8/15 = 16/15 (Wallis). Forgetting the factor 2 from dx = 2 du gives 8/15.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-70", "question": "The area of the region between the curve y = x(x − 1)(x − 2) and the x-axis for 0 ≤ x ≤ 2 is:", "options": ["0", "1/2", "1/4", "1"], "answer": 1, "explanation": "The cubic is positive on (0, 1) and negative on (1, 2). ∫₀¹ x(x − 1)(x − 2) dx = 1/4 and ∫₁² is −1/4, so the area is 1/4 + 1/4 = 1/2. The signed integral ∫₀² = 0 is the trap.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-71", "question": "The area of the region {(x, y): x² ≤ y ≤ √(2 − x²)} is:", "options": ["π/2 − 1/3", "π + 2/3", "π/2 + 1/3", "π/4 + 1/3"], "answer": 2, "explanation": "y = x² meets x² + y² = 2 where y + y² = 2, i.e. y = 1, x = ±1. Area = ∫₋₁¹ (√(2 − x²) − x²) dx = [x√(2 − x²)/2 + sin⁻¹(x/√2)]₋₁¹ − 2/3 = (1 + π/2) − 2/3 = π/2 + 1/3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-72","question":"lim (n → ∞) Σ (r = 1 to 2n) r/(n√(n² + r²)) equals:","options":["(√5 − 1)/2","√2 − 1","√5","√5 − 1"],"answer":3,"explanation":"Each term is (1/n)·(r/n)/√(1 + (r/n)²). As r runs to 2n, r/n runs over (0, 2], so the limit is ∫₀² x/√(1 + x²) dx = [√(1 + x²)]₀² = √5 − 1. Taking the upper limit 1 (from habit) gives √2 − 1.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-73", "question": "With [·] the greatest integer function, ∫₀^π [2 sin x] dx equals:", "options": ["2π/3", "π", "π/3", "4π/3"], "answer": 0, "explanation": "On (0, π), 2 sin x ∈ (0, 2]: [2 sin x] = 1 when sin x ≥ 1/2, i.e. x ∈ [π/6, 5π/6], and 0 otherwise; the value 2 occurs only at the single point π/2, which does not affect the integral. So the integral is 5π/6 − π/6 = 2π/3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-74","question":"If Iₙ = ∫₀¹ xⁿeˣ dx, then I₃ equals:","options":["2e − 6","6 − 2e","e − 3","6 − e"],"answer":1,"explanation":"By parts, Iₙ = e − n·Iₙ₋₁. I₀ = e − 1, I₁ = e − (e − 1) = 1, I₂ = e − 2, I₃ = e − 3(e − 2) = 6 − 2e ≈ 0.563 (positive, as it must be). A sign slip in the recurrence gives 2e − 6 < 0, impossible for a positive integrand.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-75","question":"∫₀^(π/2) sin 2x · tan⁻¹(sin x) dx equals:","options":["π/4 − 1/2","π/2","π/2 − 1","1 − π/4"],"answer":2,"explanation":"Put u = sin x, du = cos x dx: ∫₀¹ 2u tan⁻¹u du = [u² tan⁻¹u]₀¹ − ∫₀¹ u²/(1 + u²) du = π/4 − (1 − π/4) = π/2 − 1.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-76", "question": "∫₀^∞ (ln x)/(1 + x²) dx equals:", "options": ["π/2", "−π/2", "π ln 2", "0"], "answer": 3, "explanation": "Put x = 1/t: dx = −dt/t² and the integral becomes ∫₀^∞ (−ln t)/(1 + t²) dt = −I. So I = −I, I = 0 (the parts over (0, 1) and (1, ∞) cancel; the integral converges).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-definite-integrals-area-77", "question": "∫₀¹ (x³ − 1)/ln x dx equals:", "options": ["ln 3", "2 ln 2", "3", "1/4"], "answer": 1, "explanation": "Let F(a) = ∫₀¹ (xᵃ − 1)/ln x dx. Then F′(a) = ∫₀¹ xᵃ dx = 1/(a + 1), and F(0) = 0, so F(a) = ln(1 + a). F(3) = ln 4 = 2 ln 2.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-definite-integrals-area-78", "question": "The area of the region enclosed by the curve y = x³ and its tangent at the point (1, 1) is:", "options": ["27/4", "9/4", "27/2", "15/4"], "answer": 0, "explanation": "Tangent: y = 3x − 2. x³ − 3x + 2 = (x − 1)²(x + 2), so it meets the curve again at x = −2. On [−2, 1] the cubic lies above the line: area = ∫₋₂¹ (x³ − 3x + 2) dx = [x⁴/4 − 3x²/2 + 2x]₋₂¹ = 3/4 − (−6) = 27/4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-79","question":"The area of the region enclosed by the parabola y = x² and its normal at the point (1, 1) is:","options":["125/24","125/48","125/96","9/8"],"answer":1,"explanation":"Slope of tangent 2, so the normal is y − 1 = −(x − 1)/2, i.e. y = (3 − x)/2. x² = (3 − x)/2 ⇒ 2x² + x − 3 = 0 ⇒ x = 1, −3/2. Area = ∫ from −3/2 to 1 of ((3 − x)/2 − x²) dx = [3x/2 − x²/4 − x³/3] from −3/2 to 1 = 11/12 − (−27/16) = 125/48. (Check: a parabola–chord area is |a|(β − α)³/6 = (5/2)³/6 = 125/48.)","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-definite-integrals-area-80","question":"How many of the following are correct?\n(1) ∫₀^(2π) sin³x dx = 0.\n(2) ∫₋₁¹ e^|x| dx = e − 1.\n(3) ∫₀^(π/2) ln(sin x) dx = 0.\n(4) ∫₀¹ dx/√x does not exist (diverges).","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"(1) true: sin³(2π − x) = −sin³x. (2) false: the integrand is even, so the value is 2∫₀¹ eˣ dx = 2(e − 1). (3) false: ln(sin x) < 0 on (0, π/2) and the integral equals −(π/2) ln 2. (4) false: it converges to [2√x]₀¹ = 2. Only one is correct.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-definite-integrals-area-81", "question": "The value of ∫₀¹ e^(−x²) dx lies in the interval:", "options": ["(1/2, 2/3)", "(1, 4/3)", "(2/3, 1)", "(0, 1/2)"], "answer": 2, "explanation": "For 0 < x ≤ 1, 1 − x² < e^(−x²) < 1 (since e^u > 1 + u for u ≠ 0). Integrating: 1 − 1/3 < I < 1, i.e. 2/3 < I < 1 (in fact I ≈ 0.747).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-82", "question": "∫₀^(10π + π/3) |sin x| dx equals:", "options": ["20", "21", "61/3", "41/2"], "answer": 3, "explanation": "|sin x| has period π with ∫₀^π |sin x| dx = 2, so the first 10π give 20. The remaining ∫₀^(π/3) sin x dx = 1 − cos(π/3) = 1/2. Total 20.5 = 41/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-83", "question": "∫₀^(π/2) sin²x/(sin x + cos x) dx equals:", "options": ["(1/√2) ln(1 + √2)", "√2 ln(1 + √2)", "π/4", "(1/2) ln(1 + √2)"], "answer": 0, "explanation": "x → π/2 − x turns sin² into cos², so 2I = ∫₀^(π/2) dx/(sin x + cos x) = (1/√2)∫₀^(π/2) sec(x − π/4) dx = (1/√2)·2 ln(√2 + 1). Hence I = (1/√2) ln(1 + √2). Forgetting to halve gives √2 ln(1 + √2).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-definite-integrals-area-84", "question": "The area of the region {(x, y): x² + y² ≤ 4, y ≥ √3|x|} is:", "options": ["π/3", "2π/3", "4π/3", "π"], "answer": 1, "explanation": "y ≥ √3|x| is the wedge between the rays at 60° and 120° from the positive x-axis — an angle of π/3 at the centre. The region is a sector of radius 2 and angle π/3: area = (1/2)·4·(π/3) = 2π/3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-definite-integrals-area-85","question":"The area enclosed by the curve x^(2/3) + y^(2/3) = 1 is:","options":["π/4","3π/4","3π/8","π/8"],"answer":2,"explanation":"Parametrise x = cos³θ, y = sin³θ. Area = 4∫ y dx over the first quadrant = 4∫₀^(π/2) sin³θ · 3cos²θ sin θ dθ = 12∫₀^(π/2) sin⁴θ cos²θ dθ = 12·(3·1·1)/(6·4·2)·(π/2) = 12·π/32 = 3π/8.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-definite-integrals-area-86","question":"∫₁⁴ dx/√x equals:","options":["2","1","4","3/2"],"answer":0,"explanation":"An antiderivative of x^(−1/2) is 2√x. So the integral is 2√4 − 2√1 = 4 − 2 = 2.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-definite-integrals-area-87","question":"∫₀^(π/2) sin 2x dx equals:","options":["0","1","2","1/2"],"answer":1,"explanation":"[−cos 2x/2] from 0 to π/2 = (−cos π + cos 0)/2 = (1 + 1)/2 = 1.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-definite-integrals-area-88","question":"∫₀^(π/2) (sin x − cos x)/(1 + sin x cos x) dx equals:","options":["π/4","1","0","ln 2"],"answer":2,"explanation":"Replace x by π/2 − x: sin and cos swap, so the integral equals its own negative. Hence it is 0.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-89","question":"∫₀² x√(2 − x) dx equals:","options":["8√2/15","4√2/3","16/15","16√2/15"],"answer":3,"explanation":"Put t = 2 − x: ∫₀² (2 − t)√t dt = [ (4/3)t^(3/2) − (2/5)t^(5/2) ]₀² = (4/3)(2√2) − (2/5)(4√2) = 8√2/3 − 8√2/5 = 16√2/15.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-90","question":"The total area enclosed between the curves y = x³ and y = x is:","options":["1/4","1","1/2","1/3"],"answer":2,"explanation":"They meet at x = −1, 0, 1, enclosing two congruent regions (by odd symmetry). Each has area ∫₀¹ (x − x³) dx = 1/2 − 1/4 = 1/4, so the total is 1/2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-91","question":"∫₀³ |x² − 3x + 2| dx equals:","options":["11/6","3/2","5/6","13/6"],"answer":0,"explanation":"The quadratic (x − 1)(x − 2) is negative only on (1, 2). ∫₀¹ = 5/6, ∫₁² of its negative = 1/6, ∫₂³ = 5/6. Total 11/6.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-92","question":"For 0 < x < π/2, d/dx ∫₀^(sin x) √(1 − t²) dt equals:","options":["cos x","sin x cos x","√(1 − sin x)","cos²x"],"answer":3,"explanation":"By the Leibniz rule the derivative is √(1 − sin²x) × d(sin x)/dx = |cos x| cos x = cos²x on (0, π/2).","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-93","question":"∫₀^π x/(1 + sin²x) dx equals:","options":["π²/2","π²/(2√2)","π/√2","π²/4"],"answer":1,"explanation":"With x → π − x, I = (π/2)∫₀^π dx/(1 + sin²x) = π∫₀^(π/2) dx/(1 + sin²x). Dividing by cos²x: ∫₀^∞ dt/(1 + 2t²) = π/(2√2) (t = tan x). So I = π²/(2√2).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-94","question":"∫₀^(π/2) ln(tan x) dx equals:","options":["−(π/2) ln 2","0","(π/2) ln 2","π/4"],"answer":1,"explanation":"Under x → π/2 − x, tan x becomes cot x and ln(cot x) = −ln(tan x). So the integral equals its own negative and is 0 (the integral converges at both ends).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-95","question":"∫₀^(2π) dx/(1 + e^(sin x)) equals:","options":["2π","π/2","0","π"],"answer":3,"explanation":"Pair x with x + π: sin(x + π) = −sin x, and 1/(1 + eᵘ) + 1/(1 + e⁻ᵘ) = 1. So each pair of half-periods contributes 1 per unit length over [0, π]: the integral is π.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-96","question":"∫₀^∞ e⁻ˣ sin x dx equals:","options":["1/2","1","0","π/4"],"answer":0,"explanation":"An antiderivative is −e⁻ˣ(sin x + cos x)/2. It vanishes at ∞ and equals −1/2 at 0, so the integral is 0 − (−1/2) = 1/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-97","question":"The area of the region bounded by y = eˣ, y = e⁻ˣ and the line x = 1 is:","options":["e − 1/e","e − 1","e + 1/e − 2","2"],"answer":2,"explanation":"The curves meet at x = 0 and eˣ ≥ e⁻ˣ on [0, 1]. Area = ∫₀¹ (eˣ − e⁻ˣ) dx = (e − 1) + (e⁻¹ − 1) = e + 1/e − 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-98","question":"∫₀¹ x ln x dx equals:","options":["−1/2","1/4","0","−1/4"],"answer":3,"explanation":"By parts: ∫ x ln x dx = (x²/2) ln x − x²/4. At 1 this is −1/4, and as x → 0⁺, x² ln x → 0. So the value is −1/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-99","question":"lim (n → ∞) Σ (r = 1 to n) r/(n² + r²) equals:","options":["ln 2","π/4","(1/2) ln 2","1/2"],"answer":2,"explanation":"r/(n² + r²) = (1/n) × (r/n)/(1 + (r/n)²). The sum is a Riemann sum for ∫₀¹ x/(1 + x²) dx = (1/2) ln 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-100","question":"The area of the region bounded by y = ln x, y = −ln x and the line x = e is:","options":["1","2","e − 1","2(e − 1)"],"answer":1,"explanation":"The curves meet at (1, 0), and between x = 1 and x = e, ln x lies above −ln x. Area = ∫₁ᵉ 2 ln x dx = 2[x ln x − x]₁ᵉ = 2(0 + 1) = 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-101","question":"The area of the smaller region cut off from the disc x² + y² ≤ 2x by the line y = x is:","options":["π/4 − 1/2","π/2 − 1","π/4","1/2"],"answer":0,"explanation":"The disc has centre (1, 0) and radius 1. The line meets the circle at (0, 0) and (1, 1), and the radii to these points are perpendicular, so the chord subtends 90°. The segment area is (1/2)r²(θ − sin θ) = (1/2)(π/2 − 1) = π/4 − 1/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-102","question":"∫₀^π |cos x − sin x| dx equals:","options":["2√2","2","√2","0"],"answer":0,"explanation":"cos x − sin x = √2 cos(x + π/4). As x runs over [0, π], x + π/4 runs over an interval of length π, on which ∫|cos| = 2. So the integral is 2√2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-103","question":"∫₀¹ dx/(1 + x²)² equals:","options":["π/4","π/8 + 1/4","π/8","π/8 − 1/4"],"answer":1,"explanation":"With x = tan θ: ∫₀^(π/4) cos²θ dθ = [θ/2 + sin 2θ/4]₀^(π/4) = π/8 + 1/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-104","question":"∫₀^(π/4) sec⁴x dx equals:","options":["1","2/3","4/3","π/4 + 1/3"],"answer":2,"explanation":"sec⁴x dx = (1 + tan²x) sec²x dx = (1 + t²) dt with t = tan x from 0 to 1. So the integral is 1 + 1/3 = 4/3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-105","question":"∫₀^(π/2) x/(sin x + cos x) dx equals:","options":["(π/√2) ln(1 + √2)","(π/4) ln(1 + √2)","(π/(2√2)) ln 2","(π/(2√2)) ln(1 + √2)"],"answer":3,"explanation":"King's rule (x → π/2 − x) gives I = (π/4)∫₀^(π/2) dx/(sin x + cos x). Since sin x + cos x = √2 sin(x + π/4), that integral is (1/√2)∫ cosec u du over [π/4, 3π/4] = (1/√2) × 2 ln(√2 + 1). So I = (π/(2√2)) ln(1 + √2).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-106","question":"∫₀^π x sin x cos²x dx equals:","options":["π/2","2π/3","π/3","π/6"],"answer":2,"explanation":"With x → π − x the integrand's trigonometric part is unchanged, so I = (π/2)∫₀^π sin x cos²x dx = (π/2)[−cos³x/3]₀^π = (π/2)(2/3) = π/3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-107","question":"∫₀^∞ dx/[(1 + x²)(1 + x²⁰²⁶)] equals:","options":["π/4","π/2","π/2026","0"],"answer":0,"explanation":"Substitute x = 1/t: the integral becomes ∫₀^∞ t²⁰²⁶ dt/[(1 + t²)(1 + t²⁰²⁶)]. Adding the two forms, 2I = ∫₀^∞ dx/(1 + x²) = π/2, so I = π/4 whatever the exponent.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-108","question":"∫₀^(π/2) sin⁸x dx equals:","options":["35π/128","7π/64","63π/512","35π/256"],"answer":3,"explanation":"Wallis' formula for even n: ∫₀^(π/2) sinⁿx dx = [(n − 1)(n − 3)…1]/[n(n − 2)…2] × π/2. For n = 8: (7·5·3·1)/(8·6·4·2) × π/2 = (105/384)(π/2) = 35π/256.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-109","question":"The area of the region {(x, y): |x| + |y| ≤ 2 and x² + y² ≥ 2} is:","options":["4 − π","8 − 2π","8 − π","2π − 4"],"answer":1,"explanation":"|x| + |y| ≤ 2 is a square with diagonals 4, area 8. The distance from the origin to its sides is 2/√2 = √2, so the circle x² + y² = 2 is inscribed in it. The required area is 8 − 2π.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-110","question":"f is continuous on [0, 2] and f(x) + f(2 − x) = 4 for every x in [0, 2]. Then ∫₀² f(x) dx equals:","options":["2","4","8","a value that depends on f"],"answer":1,"explanation":"By x → 2 − x, ∫₀² f(x) dx = ∫₀² f(2 − x) dx. Adding, 2I = ∫₀² [f(x) + f(2 − x)] dx = ∫₀² 4 dx = 8, so I = 4 for every such f.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-111","question":"lim (n → ∞) (1/n) Σ (r = 1 to n) sin(rπ/n) equals:","options":["1/π","π/2","1","2/π"],"answer":3,"explanation":"This is the Riemann sum for ∫₀¹ sin(πx) dx = [−cos(πx)/π]₀¹ = 2/π.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-112","question":"∫₀^π ln(1 + cos x) dx equals:","options":["−π ln 2","π ln 2","−(π/2) ln 2","0"],"answer":0,"explanation":"1 + cos x = 2cos²(x/2), so the integral is π ln 2 + 2∫₀^π ln cos(x/2) dx = π ln 2 + 4∫₀^(π/2) ln cos t dt. Using ∫₀^(π/2) ln cos t dt = −(π/2) ln 2, the value is π ln 2 − 2π ln 2 = −π ln 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-113","question":"The total area of the regions enclosed between the curve y = x² − 4|x| + 3 and the x-axis is:","options":["8/3","4","16/3","32/3"],"answer":2,"explanation":"The curve is even. For x ≥ 0 it is x² − 4x + 3 = (x − 1)(x − 3): above the axis on [0, 1] (area 4/3, joining its mirror image) and below it on [1, 3] (area 4/3). Doubling for x < 0: 2(4/3 + 4/3) = 16/3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-114","question":"∫₀^(π/2) sin x · sin 2x · sin 3x dx equals:","options":["1/3","0","1/4","1/6"],"answer":3,"explanation":"sin x sin 3x = (cos 2x − cos 4x)/2, and multiplying by sin 2x gives (sin 2x + sin 4x − sin 6x)/4. Over [0, π/2] these integrate to 1, 0 and 1/3, so the value is (1 + 0 − 1/3)/4 = 1/6.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-115","question":"∫ from 1/e to e of |ln x| dx equals:","options":["2","2/e","2 − 2/e","e − 1/e"],"answer":2,"explanation":"With F(x) = x ln x − x: ∫₁ᵉ ln x dx = F(e) − F(1) = 1, and ∫ from 1/e to 1 of (−ln x) dx = F(1/e) − F(1) = −2/e + 1. The total is 2 − 2/e.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-116","question":"The area of the region bounded by the curve y = tan x, its tangent at x = π/4, and the x-axis is:","options":["ln 2 − 1/2","(1/2) ln 2 − 1/4","(1/2) ln 2","1/4"],"answer":1,"explanation":"The tangent at (π/4, 1) has slope sec²(π/4) = 2 and meets the x-axis at x = π/4 − 1/2. Since tan x is convex, the curve lies above the tangent. The region is the area under tan x on [0, π/4], which is (1/2) ln 2, minus the triangle under the tangent, of area (1/2)(1/2)(1) = 1/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-117","question":"∫₀¹ dx/(x + √(1 − x²)) equals:","options":["π/4","π/2","1","ln(1 + √2)"],"answer":0,"explanation":"Put x = sin θ: I = ∫₀^(π/2) cos θ dθ/(sin θ + cos θ). The companion integral with sin θ on top is equal by θ → π/2 − θ, and the two add to π/2. So I = π/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-118","question":"∫₀¹ √(x/(1 − x)) dx equals:","options":["π/2","π/4","1","2"],"answer":0,"explanation":"Put x = sin²θ, dx = 2 sin θ cos θ dθ: the integrand becomes (sin θ/cos θ)(2 sin θ cos θ) = 2sin²θ. So I = ∫₀^(π/2) 2sin²θ dθ = π/2 (an improper but convergent integral).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-119","question":"∫₀^∞ x³e⁻ˣ dx equals:","options":["3","6","24","1"],"answer":1,"explanation":"Integrating by parts repeatedly, ∫₀^∞ xⁿe⁻ˣ dx = n × ∫₀^∞ xⁿ⁻¹e⁻ˣ dx, and ∫₀^∞ e⁻ˣ dx = 1. So the value is 3! = 6.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-120","question":"∫₋₁¹ (sin x + |x|)/(1 + |x|) dx equals:","options":["2 − 2 ln 2","1 − ln 2","2 ln 2","ln 2"],"answer":0,"explanation":"sin x/(1 + |x|) is odd and integrates to zero, while |x|/(1 + |x|) is even, so I = 2∫₀¹ x/(1 + x) dx = 2∫₀¹ [1 − 1/(1 + x)] dx = 2(1 − ln 2). 1 − ln 2 forgets the doubling.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-121","question":"lim (x → 0⁺) [∫₀^(x²) sin(√t) dt]/x³ equals:","options":["1/3","2/3","1","0"],"answer":1,"explanation":"By L'Hospital's rule and the Leibniz rule, the limit is lim 2x·sin(√(x²))/(3x²) = lim 2 sin x/(3x) = 2/3. Forgetting the factor 2x from the upper limit x² gives 1/3.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-122","question":"For f(x) = ∫₀ˣ (t − 1)(t − 2)² dt, the points of local extremum of f are:","options":["a local maximum at x = 1 and a local minimum at x = 2","local minima at both x = 1 and x = 2","only a local minimum at x = 1","only a local maximum at x = 1"],"answer":2,"explanation":"f′(x) = (x − 1)(x − 2)² changes sign from negative to positive at x = 1, giving a local minimum, but does not change sign at x = 2 because (x − 2)² ≥ 0, so x = 2 is not an extremum.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-123","question":"∫₀^(π/2) sin⁴x cos⁶x dx equals:","options":["3/256","3π/256","π/512","3π/512"],"answer":3,"explanation":"By the Wallis formula with both powers even, I = [(3·1)(5·3·1)/(10·8·6·4·2)]·(π/2) = (45/3840)(π/2) = 3π/512. Leaving out the factor π/2 that goes with two even powers gives 3/256.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-124","question":"∫₀^(2π) dx/(5 − 3 cos x) equals:","options":["π/2","π/4","π","2π/√34"],"answer":0,"explanation":"For a > |b|, ∫₀^(2π) dx/(a + b cos x) = 2π/√(a² − b²) (via t = tan(x/2) over each half period), here 2π/√(25 − 9) = π/2. Using √(a² + b²) gives 2π/√34.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-125","question":"∫₀^∞ x dx/[(1 + x)(1 + x²)] equals:","options":["π/2","π/4","(1/2) ln 2","the integral diverges"],"answer":1,"explanation":"x/[(1 + x)(1 + x²)] = −1/[2(1 + x)] + (x + 1)/[2(1 + x²)]. The two logarithms combine into (1/4) ln[(1 + x²)/(1 + x)²], which tends to 0 at both ends, leaving (1/2)tan⁻¹x from 0 to ∞ = π/4. Each logarithm alone diverges, but their combination does not.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-126","question":"lim (n → ∞) Σ (r = 1 to n) 1/√(n² + 2rn) equals:","options":["√3","2(√3 − 1)","(√3 − 1)/2","√3 − 1"],"answer":3,"explanation":"Write the term as (1/n)·1/√(1 + 2r/n); the sum tends to ∫₀¹ dx/√(1 + 2x) = [√(1 + 2x)]₀¹ = √3 − 1. Forgetting the 1/2 from the inner derivative gives 2(√3 − 1).","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-127","question":"The area of the region enclosed by the parabola y = x² − 2x and the line y = x is:","options":["9/2","9/4","27/2","4/3"],"answer":0,"explanation":"They meet where x² − 2x = x, at x = 0 and 3, and the line lies above in between: ∫₀³ (3x − x²) dx = 27/2 − 9 = 9/2. 27/2 is only the integral of 3x.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-128","question":"The area of the region {(x, y): y² ≤ 2x and x² + y² ≤ 8} is:","options":["6π − 4/3","2π + 4/3","π + 2/3","2π + 8/3"],"answer":1,"explanation":"The curves meet at (2, ±2). By symmetry the area is 2[∫₀² √(2x) dx + ∫₂^(2√2) √(8 − x²) dx] = 2[8/3 + (π − 2)] = 2π + 4/3. 6π − 4/3 is the rest of the disc, and π + 2/3 forgets the factor 2 for the lower half.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-129","question":"The area of the region bounded by the curve y = eˣ, the line y = e and the y-axis is:","options":["e − 1","e","1","e − 2"],"answer":2,"explanation":"For 0 ≤ x ≤ 1 the line y = e lies above y = eˣ, so the area is ∫₀¹ (e − eˣ) dx = e − (e − 1) = 1. e − 1 is the area under the curve instead.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-130","question":"The total area enclosed between the curves y = x|x| and y = x³ is:","options":["1/12","0","1/3","1/6"],"answer":3,"explanation":"For x ≥ 0 they enclose ∫₀¹ (x² − x³) dx = 1/12; for x ≤ 0 the curves are y = −x² and y = x³, meeting at x = −1 and enclosing ∫₋₁⁰ (x³ + x²) dx = 1/12. The total is 1/6. A single signed integral over [−1, 1] gives 0.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-131","question":"The horizontal line y = c divides the region enclosed by y = x² and y = 4 into two parts of equal area. Then c equals:","options":["4^(2/3)","2","2√2","2^(5/3)"],"answer":0,"explanation":"The area between y = x² and y = c is (4/3)c^(3/2), so (4/3)c^(3/2) = (1/2)(4/3)(8), giving c^(3/2) = 4 and c = 4^(2/3) = 2∛2. Halving the height gives 2, and treating the area as ∝ c² gives 2√2.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-132","question":"∫ from 1/2 to 2 of (1/x) sin(x − 1/x) dx equals:","options":["ln 4","0","2 sin(3/2)","sin(3/2)·ln 4"],"answer":1,"explanation":"Put x = 1/t: dx/x = −dt/t, the limits swap back to 1/2 and 2, and sin(1/t − t) = −sin(t − 1/t), so I = −I and I = 0. The integrand is not odd in x, but it is 'odd' under x → 1/x.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-133","question":"Let I = ∫₀¹ e^(x²) dx. Then:","options":["I < 1","I = e − 1","4/3 < I < e","I > e"],"answer":2,"explanation":"On (0, 1), 1 + x² < e^(x²) < e, so ∫₀¹ (1 + x²) dx = 4/3 < I < e (in fact I ≈ 1.46). I = e − 1 would be ∫₀¹ eˣ dx, a different integral.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-134","question":"∫₀^(π/2) x² cos x dx equals:","options":["π²/4","2 − π²/4","π²/2 − 2","π²/4 − 2"],"answer":3,"explanation":"Integrating by parts twice, ∫x² cos x dx = x² sin x + 2x cos x − 2 sin x, which gives π²/4 + 0 − 2 = π²/4 − 2. Stopping after the first term gives π²/4, and a sign slip in the second step gives 2 − π²/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-135","question":"∫₀^(100π) √(1 − cos 2x) dx equals:","options":["200√2","0","100√2","200"],"answer":0,"explanation":"√(1 − cos 2x) = √2|sin x|, which has period π and integrates to 2 over each period, so the integral is √2 × 100 × 2 = 200√2. Writing √2 sin x without the modulus gives 0.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-136","question":"The area of the region enclosed by the parabola y² = 4ax and its latus rectum is:","options":["4a²/3","8a²/3","16a²/3","2a²"],"answer":1,"explanation":"The latus rectum is x = a, so the area is 2∫₀ᵃ 2√(ax) dx = 4√a·(2/3)a^(3/2) = 8a²/3. Counting only the half above the axis gives 4a²/3.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-137","question":"The total area enclosed between the curve y = x(x − 1)(x − 2) and the x-axis is:","options":["0","1/4","1/2","1"],"answer":2,"explanation":"The cubic is positive on (0, 1) and negative on (1, 2), and by symmetry about (1, 0) each lobe has area ∫₀¹ (x³ − 3x² + 2x) dx = 1/4, so the total is 1/2. The signed integral from 0 to 2 is 0.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-138","question":"∫₀^π x sin³x dx equals:","options":["4/3","π/3","4π/3","2π/3"],"answer":3,"explanation":"Using ∫₀^π x f(sin x) dx = (π/2)∫₀^π f(sin x) dx and ∫₀^π sin³x dx = 4/3, the integral is (π/2)(4/3) = 2π/3. Forgetting the factor 1/2 gives 4π/3, and 4/3 is ∫₀^π sin³x dx alone.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-139","question":"∫₀^(π/2) eˣ(sin x + cos x) dx equals:","options":["e^(π/2)","e^(π/2) − 1","2e^(π/2)","−1"],"answer":0,"explanation":"(eˣ sin x)′ = eˣ(sin x + cos x), so the integral is [eˣ sin x]₀^(π/2) = e^(π/2). Taking eˣ(sin x + cos x) as the antiderivative gives e^(π/2) − 1, and eˣ cos x gives −1.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-definite-integrals-area-140","question":"The area enclosed by the curve y² = x²(1 − x²) is:","options":["2/3","4/3","8/3","π/2"],"answer":1,"explanation":"The curve is a figure-of-eight, symmetric in both axes, with x ranging over [−1, 1]. Its area is 4∫₀¹ x√(1 − x²) dx = 4 × 1/3 = 4/3. Counting only the loop on one side of the y-axis gives 2/3.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-141","question":"The area of the region bounded by the curve y = ln x, its tangent that passes through the origin, and the x-axis is:","options":["e/2","1","e/2 − 1","e/2 − 1/(2e) − 1"],"answer":2,"explanation":"The tangent at (a, ln a) passes through O when ln a = 1, i.e. at (e, 1), and is y = x/e. The area is the triangle under the tangent from 0 to e, e/2, minus the area under ln x from 1 to e, which is 1: e/2 − 1. Starting the tangent's integral at x = 1 gives e/2 − 1/(2e) − 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-definite-integrals-area-142","question":"∫₀^(π/2) ln(sin 2x) dx equals:","options":["−π ln 2","0","−(π/2) ln 2","−(π/4) ln 2"],"answer":2,"explanation":"With u = 2x, I = (1/2)∫₀^π ln(sin u) du = ∫₀^(π/2) ln(sin u) du = −(π/2) ln 2. Splitting ln(sin 2x) = ln 2 + ln sin x + ln cos x gives (π/2) ln 2 − π ln 2 = −(π/2) ln 2 again; forgetting the ln 2 term gives −π ln 2.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-definite-integrals-area-143","question":"∫₀² tan⁻¹(2/(x − 1)²) dx equals:","options":["4 tan⁻¹2 − ln 5","2 tan⁻¹2 − (1/2) ln 5","4 tan⁻¹2 − 2 ln 5","π − ln 5"],"answer":0,"explanation":"Since x(2 − x) ≤ 1, tan⁻¹x + tan⁻¹(2 − x) = tan⁻¹(2/(1 − 2x + x²)), so the integral is 2∫₀² tan⁻¹x dx = 2[2 tan⁻¹2 − (1/2) ln 5].","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-144","question":"For x > 0 let f(x) = ∫₁ˣ (tan⁻¹t)/t dt. Then f(e) − f(1/e) equals:","options":["π/4","0","π","π/2"],"answer":3,"explanation":"Put t = 1/u in f(1/x): since tan⁻¹(1/u) = π/2 − tan⁻¹u for u > 0, f(1/x) = f(x) − (π/2) ln x. So f(e) − f(1/e) = (π/2) ln e = π/2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-145","question":"lim (n → ∞) Σ (r = 1 to n) n/[(n + r)√(r(2n + r))] equals:","options":["π/4","π/6","π/3","π/2"],"answer":2,"explanation":"Each term is (1/n)·1/[(1 + x)√(x(2 + x))] with x = r/n, and x(2 + x) = (1 + x)² − 1. So the limit is ∫₀¹ dx/[(1 + x)√((1 + x)² − 1)] = sec⁻¹2 − sec⁻¹1 = π/3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-146","question":"The area of the region {(x, y): |x − 1| ≤ y ≤ √(5 − x²)} is:","options":["5π/4 − 1","5π/4 − 1/2","5π/4 − 3/2","5π/2 − 5/2"],"answer":1,"explanation":"The boundaries meet at x = −1 and x = 2. ∫₋₁² √(5 − x²) dx = 2 + (5/2)[sin⁻¹(2/√5) + sin⁻¹(1/√5)] = 2 + 5π/4, and ∫₋₁² |x − 1| dx = 5/2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-147","question":"The area of the region enclosed between the curves y = ln x and y = (ln x)² is:","options":["e − 2","3 − e","e − 1","2e − 5"],"answer":1,"explanation":"They meet at x = 1 and x = e, with ln x ≥ (ln x)² in between. ∫₁ᵉ ln x dx = 1 and ∫₁ᵉ (ln x)² dx = e − 2, so the area is 1 − (e − 2) = 3 − e.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-148","question":"The line y = mx divides the region enclosed by y = 2x − x² and the x-axis into two parts of equal area. Then m equals:","options":["2 − ∛4","2 − ∛2","1","2 − ∛6"],"answer":0,"explanation":"The whole region has area 4/3. The part between the parabola and the line (they meet at x = 2 − m) has area (2 − m)³/6; setting it to 2/3 gives (2 − m)³ = 4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-149","question":"With [·] the greatest integer function, ∫₀^(2π) [sin x + cos x] dx equals:","options":["−π/2","−3π/4","−3π/2","−π"],"answer":3,"explanation":"sin x + cos x = √2 sin(x + π/4). The integrand is 1 on (0, π/2), 0 on (π/2, 3π/4), −1 on (3π/4, π), −2 on (π, 3π/2), −1 on (3π/2, 7π/4) and 0 after. Total π/2 − π/4 − π − π/4 = −π.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-150","question":"With [·] the greatest integer function, ∫₀⁹ [√x] dx equals:","options":["14","12","13","19"],"answer":2,"explanation":"[√x] = 0 on [0, 1), 1 on [1, 4) and 2 on [4, 9). The integral is 0·1 + 1·3 + 2·5 = 13.","difficulty":"moderate","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-151","question":"∫₀¹ x⁴/(1 + x²) dx equals:","options":["π/4 − 1/2","π/4 − 1/3","π/4 − 2/3","4/3 − π/4"],"answer":2,"explanation":"x⁴/(1 + x²) = x² − 1 + 1/(1 + x²), so the integral is 1/3 − 1 + π/4 = π/4 − 2/3.","difficulty":"moderate","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-152","question":"The area of the region enclosed by y = x² and y = 2/(1 + x²) is:","options":["π/2 − 1/3","π − 2/3","π − 1/3","2π − 2/3"],"answer":1,"explanation":"The curves meet where x⁴ + x² − 2 = 0, i.e. x = ±1. Area = ∫₋₁¹ [2/(1 + x²) − x²] dx = 2·(π/2) − 2/3.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-153","question":"For f(x) = x³ + x, the value of ∫₀² f⁻¹(x) dx is:","options":["5/4","3/4","1/2","7/4"],"answer":0,"explanation":"f(0) = 0 and f(1) = 2. By the inverse-function area rule, ∫₀² f⁻¹(x) dx = 1·2 − ∫₀¹ (x³ + x) dx = 2 − 3/4 = 5/4.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-154","question":"With {·} the fractional part, ∫₋₂² min({x}, {−x}) dx equals:","options":["2","1/2","4/3","1"],"answer":3,"explanation":"For non-integer x, {−x} = 1 − {x}, so the integrand is min(t, 1 − t) with t = {x}, whose average over a period is 1/4. Over a length of 4 the integral is 1.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-155","question":"Let I = ∫₀^(π/2) (sin x)/x dx. Then:","options":["π/2 < I < 2","2/π < I < 1","I = 1","1 < I < π/2"],"answer":3,"explanation":"On (0, π/2), sin x/x decreases from 1 to 2/π, so (2/π)(π/2) < I < 1·(π/2), i.e. 1 < I < π/2 (strict, as the integrand is not constant).","difficulty":"moderate","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-156","question":"If Iₙ = ∫₀¹ (1 − x²)ⁿ dx, then I₅/I₄ equals:","options":["9/10","8/9","10/11","11/12"],"answer":2,"explanation":"Integrating by parts, Iₙ = 2n(I₍ₙ₋₁₎ − Iₙ), so Iₙ/I₍ₙ₋₁₎ = 2n/(2n + 1); for n = 5 this is 10/11.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-157","question":"∫₀^∞ dx/(x + √(x² + 1))³ equals:","options":["1/3","3/8","3/4","1/8"],"answer":1,"explanation":"Put x = sinh t, so x + √(x² + 1) = eᵗ and dx = cosh t dt. The integral is ∫₀^∞ e^(−3t)(eᵗ + e^(−t))/2 dt = (1/2)(1/2 + 1/4) = 3/8.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-158","question":"∫₀^π |sin x − 1/2| dx equals:","options":["2√3 − π/6 − 2","√3 − π/3","2 − π/6","2√3 − π/3 − 2"],"answer":0,"explanation":"sin x ≥ 1/2 on [π/6, 5π/6], contributing √3 − π/3. The two outer pieces contribute π/6 − (2 − √3). The sum is 2√3 − π/6 − 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-159","question":"The area of the region enclosed by the curves x = y² and x = 3 − 2y² is:","options":["4","2","8/3","6"],"answer":0,"explanation":"They meet where y² = 1. Integrating along y: ∫₋₁¹ (3 − 2y² − y²) dy = 6 − 2 = 4.","difficulty":"moderate","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-160","question":"The area of the region {(x, y): x² + y² ≤ 1 ≤ x + y} is:","options":["π/2 − 1","π − 2","π/4 − 1/4","π/4 − 1/2"],"answer":3,"explanation":"It is the segment of the unit disc cut off by the chord x + y = 1 in the first quadrant: quarter disc π/4 minus the triangle of area 1/2.","difficulty":"moderate","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-161","question":"∫₀^(π/4) x/[cos x (cos x + sin x)] dx equals:","options":["(π/4) ln 2","(π/16) ln 2","(π/8) ln 2","(π/8) ln 2 − π/8"],"answer":2,"explanation":"The integrand is x sec²x/(1 + tan x). By parts: [x ln(1 + tan x)]₀^(π/4) − ∫₀^(π/4) ln(1 + tan x) dx = (π/4) ln 2 − (π/8) ln 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-162","question":"∫₀^(π/2) x cot x dx equals:","options":["π/2 − (π/2) ln 2","(π/2) ln 2","π ln 2","(π/4) ln 2"],"answer":1,"explanation":"By parts, [x ln sin x]₀^(π/2) − ∫₀^(π/2) ln sin x dx = 0 − (−(π/2) ln 2), since x ln sin x → 0 at both ends.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-163","question":"∫₀² x√(2x − x²) dx equals:","options":["π/4","π/2","π","2π/3"],"answer":1,"explanation":"√(2x − x²) is symmetric about x = 1, so with x → 2 − x the integral equals 1·∫₀² √(2x − x²) dx, the area of a semicircle of radius 1, π/2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-164","question":"∫₀¹ x⁶√(1 − x²) dx equals:","options":["5π/256","5π/128","15π/256","5π/512"],"answer":0,"explanation":"With x = sin θ it becomes ∫₀^(π/2) sin⁶θ cos²θ dθ = (5·3·1·1)/(8·6·4·2)·(π/2) = 5π/256.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-165","question":"∫₀^(20π) (|sin x| + |cos x|) dx equals:","options":["40","40√2","20√2 π","80"],"answer":3,"explanation":"The integrand has period π/2 and ∫₀^(π/2) (sin x + cos x) dx = 2. There are 40 such periods in 20π, giving 80.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-166","question":"Let g(x) = ∫₀ˣ cos⁴t dt. Then g(x + π) equals:","options":["g(x)","g(x) + 3π/4","g(x) + g(π)","g(x) + π"],"answer":2,"explanation":"cos⁴t has period π, so ∫ₓ^(x + π) cos⁴t dt = ∫₀^π cos⁴t dt = g(π), and g(x + π) = g(x) + g(π).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-167","question":"The area between one arch of the cycloid x = t − sin t, y = 1 − cos t (0 ≤ t ≤ 2π) and the x-axis is:","options":["2π","4π","3π","π"],"answer":2,"explanation":"Area = ∫ y dx = ∫₀^(2π) (1 − cos t)² dt = ∫₀^(2π) (1 − 2 cos t + cos²t) dt = 2π + π = 3π.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-168","question":"The area of the region enclosed by y = 2ˣ and y = x + 1 is:","options":["1/ln 2 − 1/2","3/2 − 1/ln 2","3/2 − ln 2","1 − 1/(2 ln 2)"],"answer":1,"explanation":"The curves meet at x = 0 and x = 1, with the line above. Area = ∫₀¹ (x + 1 − 2ˣ) dx = 3/2 − (2 − 1)/ln 2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-169","question":"∫₋₁¹ (x² + sin x)/(1 + x²) dx equals:","options":["2 − π/2","2 − π/4","1 − π/4","π/2"],"answer":0,"explanation":"sin x/(1 + x²) is odd and integrates to 0. The rest is 2∫₀¹ [1 − 1/(1 + x²)] dx = 2(1 − π/4).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-170","question":"The area of the region enclosed by y = sin x and y = 2x/π (x ≥ 0) is:","options":["π/4 − 1/2","1 − π/2","2 − π/2","1 − π/4"],"answer":3,"explanation":"They meet at x = 0 and x = π/2, with sin x above the chord. Area = ∫₀^(π/2) (sin x − 2x/π) dx = 1 − (1/π)(π²/4).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-171","question":"lim (n → ∞) [(1 + 1/n²)(1 + 4/n²)(1 + 9/n²)⋯(1 + n²/n²)]^(1/n) equals:","options":["2e^(π/4 − 2)","e^(π/2 − 2)","2e^(π/2 − 1)","2e^(π/2 − 2)"],"answer":3,"explanation":"The log of the limit is ∫₀¹ ln(1 + x²) dx = [x ln(1 + x²)]₀¹ − ∫₀¹ 2x²/(1 + x²) dx = ln 2 − 2 + π/2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-172","question":"∫₀^(π/2) sin 2x · ln(sin x) dx equals:","options":["−1/4","−1","−1/2","−π/4"],"answer":2,"explanation":"Put u = sin x: the integral is ∫₀¹ 2u ln u du = [u² ln u − u²/2]₀¹ = −1/2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-173","question":"∫₀^π cos 2x · ln(sin x) dx equals:","options":["−π ln 2","−π/2","−(π/2) ln 2","−π/4"],"answer":1,"explanation":"By parts with v = (1/2) sin 2x: the boundary term vanishes, leaving −∫₀^π (1/2) sin 2x · cot x dx = −∫₀^π cos²x dx = −π/2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-174","question":"The area of the region enclosed by the parabola y = x² and the curve y = |2x − 3| is:","options":["32/3","16/3","28/3","12"],"answer":0,"explanation":"x² = 3 − 2x gives x = −3 and x = 1 (x² = 2x − 3 has no root). On [−3, 1], |2x − 3| = 3 − 2x, so the area is ∫₋₃¹ (3 − 2x − x²) dx = 32/3.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-175","question":"The area of the region enclosed by y = x² − 1 and y = 1 − |x| is:","options":["7/3","5/3","8/3","10/3"],"answer":0,"explanation":"x² + |x| − 2 = 0 gives |x| = 1. By symmetry the area is 2∫₀¹ (2 − x − x²) dx = 2(2 − 1/2 − 1/3) = 7/3.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-176","question":"lim (x → 0) [∫₀ˣ (sin t − t) dt]/x⁴ equals:","options":["−1/6","−1/120","−1/12","−1/24"],"answer":3,"explanation":"sin t − t = −t³/6 + O(t⁵), so the numerator is −x⁴/24 + O(x⁶). (L'Hôpital: (sin x − x)/(4x³) → −1/24.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-definite-integrals-area-177","question":"∫₀^(ln 2) √(eˣ − 1) dx equals:","options":["1 − π/4","2 − π/4","2 − π/2","π/2 − 1"],"answer":2,"explanation":"Put t = √(eˣ − 1): x = ln(1 + t²), dx = 2t dt/(1 + t²). The integral is ∫₀¹ 2t²/(1 + t²) dt = 2(1 − π/4).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
